class Board:
    def __init__(self, id, family, domain, title, principle, *aliases):
        self.id = id
        self.family = family
        self.domain = domain
        self.title = title
        self.principle = principle
        self.aliases = aliases


ROWS = [Board(*row) for row in _RAW]
_BY_ID = {row.id: row for row in ROWS}
_ALIASES = sorted(((alias, row) for row in ROWS for alias in row.aliases), key=lambda item: len(item[0]), reverse=True)
_ASK = re.compile(r"\b(what|explain|define|meaning|difference|which)\b")
_LIST = re.compile(r"\b(list|taxonomy|categories|category)\b")
_REF = re.compile(r"\b(?:tp|sw|[rcdlqjuy])\d+\b")
_VERB = re.compile(r"\b(place|connect|tie|wire|move|delete|route|remove)\b")
_SUB = str.maketrans("₀₁₂₃₄₅₆₇₈₉", "0123456789")


def _low(text: str) -> str:
    raw = text.lower().translate(_SUB).replace("₂", "2").replace("²", "2")
    return re.sub(r"[^a-z0-9]+", " ", raw).strip()


def _span(text: str, row: Board) -> int:
    padded = f" {_low(text)} "
    return max((len(alias) for alias in row.aliases if f" {alias} " in padded), default=0)


def _family_line(domain: str | None) -> str:
    counts = {key: 0 for key in _FAMILY}
    for row in ROWS:
        if domain is None or row.domain == domain or (domain == 'both'):
            counts[row.family] = counts.get(row.family, 0) + 1
    keys = [key for key in _FAMILY if counts.get(key) and (domain in (None, 'both') or _DOMAIN[key] == domain)]
    parts = [f"{_FAMILY[key]} ({counts[key]})" for key in keys]
    total = sum(counts[key] for key in keys)
    label = "Sensor" if domain == "sensor" else "Switch" if domain == "switch" else "Sensor and switch"
    return f"{label} families: {', '.join(parts)}. {total} boards. {_LIMIT}"


def families() -> str:
    return _family_line("both")


def find(text: str) -> Board | None:
    low = _low(text)
    if _REF.search(low) and _VERB.search(low):
        return None
    padded = f" {low} "
    for alias, row in _ALIASES:
        if f" {alias} " in padded:
            return row
    return None


def describe(kind: str) -> tuple[str, str] | None:
    row = _BY_ID.get(kind)
    if row is None:
        return None
    return row.title, f"{row.title}. {row.principle} {_PROFILE[row.domain]} {_LIMIT} Board class stored."


def lookup(text: str) -> dict | None:
    low = _low(text)
    words = set(low.split())
    sensorish = any(word.startswith('sensor') for word in words)
    switchish = any(word.startswith('switch') for word in words)
    if _LIST.search(low) and (sensorish or switchish):
        domain = "sensor" if sensorish and not switchish else "switch" if switchish and not sensorish else "both"
        return {"mode": "ask", "id": "", "text": _family_line(domain), "span": 0}
    row = find(text)
    if row is None:
        return None
    text_out = f"{row.title}. {row.principle} {_PROFILE[row.domain]} {_LIMIT}"
    span = _span(text, row)
    if _ASK.search(low):
        return {"mode": "ask", "id": row.id, "text": text_out, "span": span}
    return {"mode": "set", "id": row.id, "text": text_out + " Board class stored.", "span": span}


def tokens() -> list[str]:
    words = set()
    for row in ROWS:
        words.add(row.id)
        words.add(row.family)
        for alias in row.aliases:
            words.update(alias.split())
    return sorted(words)

